/**
 * @param {string} input
 * @return {string}
 */
function solve(input) {
    const data = input.trim().split(/\s+/);

    // Example input: [2,7,11,15] 9
    const nums = JSON.parse(data[0]);
    const target = Number(data[1]);

    const map = new Map();

    for (let i = 0; i < nums.length; i++) {

        const need = target - nums[i];

        if (map.has(need)) {
            return JSON.stringify([map.get(need), i]);
        }

        map.set(nums[i], i);
    }

    return JSON.stringify([]);
}

