import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.*;

public class Main {

    public static void main(String[] args) throws Exception {

        BufferedReader br = new BufferedReader(
            new InputStreamReader(System.in)
        );

        // First line: [3,2,4]
        String arrayInput = br.readLine();

        // Second line: 6
        String targetInput = br.readLine();

        if (arrayInput == null || targetInput == null) {
            return;
        }

        // Remove [ and ]
        arrayInput = arrayInput.replace("[", "")
                               .replace("]", "")
                               .trim();

        // Convert array into integers
        String[] parts = arrayInput.split(",");

        int[] nums = new int[parts.length];

        for (int i = 0; i < parts.length; i++) {
            nums[i] = Integer.parseInt(parts[i].trim());
        }

        int target = Integer.parseInt(targetInput.trim());

        // Two Sum
        HashMap<Integer, Integer> map = new HashMap<>();

        for (int i = 0; i < nums.length; i++) {

            int need = target - nums[i];

            if (map.containsKey(need)) {

                System.out.println(
                    "[" + map.get(need) + "," + i + "]"
                );

                return;
            }

            map.put(nums[i], i);
        }

        System.out.println("[]");
    }
}

