using namespace std;

int main() {
    string input;
    char ch;
    long long num;
    bool readingNumber = false;
    bool negative = false;

    vector<long long> values;

    while (cin.get(ch)) {
        if (ch == '-' && !readingNumber) {
            negative = true;
            num = 0;
            readingNumber = true;
        }
        else if (isdigit(ch)) {
            if (!readingNumber) {
                num = 0;
                readingNumber = true;
            }

            num = num * 10 + (ch - '0');
        }
        else {
            if (readingNumber) {
                values.push_back(negative ? -num : num);
                readingNumber = false;
                negative = false;
            }
        }
    }

    // Handle a number at the very end of input
    if (readingNumber) {
        values.push_back(negative ? -num : num);
    }

    if (values.size() < 3) {
        return 0;
    }

    // Last number is the target
    long long target = values.back();

    unordered_map<long long, int> seen;

    // Everything before target is the array
    for (int i = 0; i < (int)values.size() - 1; i++) {
        long long num = values[i];
        long long complement = target - num;

        if (seen.find(complement) != seen.end()) {
            cout << "[" << seen[complement] << "," << i << "]";
            return 0;
        }

        seen[num] = i;
    }

    return 0;
}

