  const target = Number(lines[1].trim());

  // Two Sum Logic - O(N) Time, O(N) Space
  const map = new Map();
  let result = [];

  for (let i = 0; i < nums.length; i++) {
    const complement = target - nums[i];

    if (map.has(complement)) {
